// The pages carry the same security policy as the server sends, for the static copy that has no server
// (GitHub Pages sends no headers). And the crew page's "?" cards (src/explain.js) open only for what is still on
// the page. Code generated by Claude (Anthropic), an AI system.
import { test, mock } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { DATA_SERVICES } from '../src/security.js';

const page = (name) => readFile(new URL(`../${name}`, import.meta.url), 'utf8');
const metaPolicy = (html) => (html.match(/<meta http-equiv="Content-Security-Policy" content="([^"]*)">/) || [])[1] || '';
const inlineHashes = (html) => [...html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi)]
  .filter((m) => !/\bsrc\s*=/i.test(m[1]))
  .map((m) => createHash('sha256').update(m[2].replace(/\r\n?/g, '\n'), 'utf8').digest('base64'));

for (const name of ['index.html', 'machine.html']) {
  test(`${name}: the policy in the page allows exactly its own inline scripts and the outside services`, async () => {
    const html = await page(name);
    const csp = metaPolicy(html);
    assert.ok(csp, 'the page has a Content-Security-Policy meta tag');
    for (const h of inlineHashes(html)) assert.ok(csp.includes(`'sha256-${h}'`), `inline script hash ${h} is in the policy (recompute after editing the script)`);
    const connect = (csp.split('; ').find((d) => d.startsWith('connect-src ')) || '').split(' ');
    for (const s of DATA_SERVICES) assert.ok(connect.includes(s), `${s} may be reached`);
    assert.ok(csp.includes("object-src 'none'") && csp.includes("base-uri 'self'"));
    assert.ok(!/script-src[^;]*'unsafe-inline'/.test(csp), 'no inline scripts beyond the hashed ones');
  });
}

// "I am okay: false alarm" takes its own message away while the pointer still rests on the button. The card that
// resting starts must then not open: it had nothing to point at and stuck in the top corner, over the Today key.
// Node has no DOM, so a very small stand-in holds just what explain.js uses.
test('a "?" card opens for a thing the pointer rests on, never for one that left the page in the meantime', async () => {
  const on = {};
  const made = [];
  const element = () => ({ hidden: false, style: {}, classList: { toggle() {}, contains: () => false }, setAttribute() {}, replaceChildren() {}, addEventListener() {}, append() {}, querySelector: () => null, contains: () => false, offsetWidth: 300, offsetHeight: 80, scrollTop: 0, clientHeight: 80, scrollHeight: 80 });
  globalThis.document = {
    createElement: () => { const el = element(); made.push(el); return el; },
    body: { append() {} },
    querySelector: () => null, // no status line or key bar here: the card may use the whole window
    getElementById: () => null,
    documentElement: { clientWidth: 1366 },
    addEventListener: (type, fn) => { (on[type] = on[type] || []).push(fn); },
  };
  globalThis.window = { innerHeight: 900, addEventListener() {} };
  mock.timers.enable({ apis: ['setTimeout'] });
  try {
    const { initTips, hideTip } = await import('../src/explain.js');
    initTips(() => ({}));
    const card = made[0];
    const thing = () => {
      const t = { dataset: { tip: 't:falsealarm' }, isConnected: true, classList: { contains: () => false }, setAttribute() {}, getBoundingClientRect: () => ({ left: 300, top: 500, width: 200, height: 40, bottom: 540 }) };
      t.closest = (sel) => (sel === '[data-tip]' ? t : null);
      return t;
    };
    const rest = (t) => { for (const fn of on.pointerover) fn({ target: t, pointerType: 'mouse' }); };
    const button = thing();
    rest(button);
    mock.timers.tick(600);
    assert.equal(card.hidden, false, 'resting on a thing opens its card');
    hideTip();
    const gone = thing();
    rest(gone);
    gone.isConnected = false; // pressed: the screen is drawn anew and the button is gone
    mock.timers.tick(600);
    assert.equal(card.hidden, true, 'no card for a thing that left the page');
  } finally {
    mock.timers.reset();
    delete globalThis.document;
    delete globalThis.window;
  }
});
